#### Problem 2: Session manager with fixation defence, families, and idle/absolute expiry

**Specification.** Opaque 256-bit session ids, stored hashed, promoted on login with atomic rotation, family-tagged to detect reuse of a retired id, dual idle/absolute expiry, and scoped revocation.

```python
import hashlib, hmac, secrets, time, dataclasses

COOKIE = "__Host-sid"
IDLE_SECONDS = 30 * 60
ABSOLUTE_SECONDS = 8 * 3600

@dataclasses.dataclass
class Session:
    key: str                # sha256 of the token
    user_id: str
    family: str
    created_at: float
    last_seen_at: float
    authenticated: bool
    revoked_at: float | None = None

class SessionStore:
    def __init__(self, db):
        self.db = db
        self.key = staticmethod(lambda tok: hashlib.sha256(tok.encode()).hexdigest())

    def create_anonymous(self, meta: dict) -> tuple[str, str]:
        sid, family = secrets.token_urlsafe(32), secrets.token_urlsafe(16)
        self.db.execute("""
            INSERT INTO sessions (key, user_id, family, created_at, last_seen_at,
                                  authenticated, ip, user_agent)
            VALUES ($1, NULL, $2, now(), now(), FALSE, $3, $4)
        """, self.key(sid), family, meta.get("ip"), meta.get("ua"))
        return sid, family

    def promote(self, anon_sid: str, user_id: str) -> str:
        """Atomically exchange an anonymous session for an authenticated one."""
        old_key = self.key(anon_sid)
        new_sid = secrets.token_urlsafe(32)
        with self.db.transaction() as tx:
            row = tx.one("SELECT * FROM sessions WHERE key = $1 FOR UPDATE", old_key)
            if row is None:
                raise SessionExpired()
            if row["authenticated"]:
                # A retired id came back: burn the family.
                tx.run("UPDATE sessions SET revoked_at = now() "
                       "WHERE family = $1 AND revoked_at IS NULL", row["family"])
                raise SessionReuseDetected(row["family"])
            tx.run("""
                INSERT INTO sessions (key, user_id, family, created_at, last_seen_at,
                                      authenticated, ip, user_agent)
                SELECT $2, $3, family, now(), now(), TRUE, ip, user_agent
                  FROM sessions WHERE key = $1
            """, old_key, self.key(new_sid), user_id)
            tx.run("DELETE FROM sessions WHERE key = $1", old_key)
        return new_sid

    def touch(self, sid: str) -> Session:
        key = self.key(sid)
        row = self.db.one("SELECT * FROM sessions WHERE key = $1", key)
        if row is None:
            raise SessionExpired()
        nowt = time.time()
        if row["revoked_at"] or nowt - row["created_at"] > ABSOLUTE_SECONDS \
           or nowt - row["last_seen_at"] > IDLE_SECONDS:
            raise SessionExpired()
        # Sample the write: at most once a minute, to avoid a per-request write storm.
        if nowt - row["last_seen_at"] > 60:
            self.db.execute("UPDATE sessions SET last_seen_at = $2 WHERE key = $1",
                            key, nowt)
            row["last_seen_at"] = nowt
        return Session(**row)

    def revoke_all_for_user(self, user_id: str, except_key: str | None = None) -> int:
        return self.db.execute("""
            UPDATE sessions SET revoked_at = now()
             WHERE user_id = $1 AND revoked_at IS NULL
               AND ($2::text IS NULL OR key <> $2)
        """, user_id, except_key).rowcount
```

