#### Problem 3: Refresh token rotation with reuse detection and a grace window

**Specification.** Single-use refresh tokens in a chain; presenting a spent token revokes the whole family; a short grace window returns the already-issued successor instead of treating the replay as theft; client binding is enforced.

```python
import dataclasses, time, uuid, secrets, hashlib, hmac

@dataclasses.dataclass
class Decision:
    action: str                       # issue | replay_within_grace | reuse | expired | revoked
    user_id: str | None = None
    family: str | None = None
    child_jti: str | None = None

class RefreshService:
    def __init__(self, db, grace_seconds: int = 10):
        self.db, self.grace = db, grace_seconds

    def issue(self, user_id: str, family: str | None = None,
              binding: str | None = None) -> tuple[str, dict]:
        fam = family or secrets.token_hex(16)
        jti = str(uuid.uuid4())
        raw = secrets.token_urlsafe(48)
        self.db.run("""
            INSERT INTO refresh_tokens (jti, token_hash, user_id, family, binding,
                                        issued_at, expires_at)
            VALUES ($1, $2, $3, $4, $5, now(), now() + interval '30 days')
        """, jti, hashlib.sha256(raw.encode()).hexdigest(), user_id, fam, binding)
        return raw, {"jti": jti, "family": fam}

    def consume(self, raw: str, binding: str | None = None) -> Decision:
        digest = hashlib.sha256(raw.encode()).hexdigest()
        # Atomic single-use: exactly one caller can win.
        row = self.db.one("""
            UPDATE refresh_tokens SET used_at = now()
             WHERE token_hash = $1 AND used_at IS NULL AND revoked_at IS NULL
            RETURNING jti, user_id, family, parent_jti, used_at
        """, digest)
        if row is None:
            return self._handle_replay(digest, binding)
        if binding is not None and not self._binding_ok(row, binding):
            self._revoke_family(row["family"], row["user_id"], "binding_mismatch")
            return Decision("reuse", row["user_id"], row["family"])
        child_raw, child = self.issue(row["user_id"], row["family"], binding)
        self.db.run("UPDATE refresh_tokens SET parent_jti = $1 WHERE jti = $2",
                    child["jti"], row["jti"])
        return Decision("issue", row["user_id"], row["family"], child["jti"])

    def _handle_replay(self, digest: str, binding: str | None) -> Decision:
        row = self.db.one("SELECT jti, user_id, family, used_at, revoked_at, expires_at "
                          "FROM refresh_tokens WHERE token_hash = $1", digest)
        if row is None:
            return Decision("expired")
        if row["used_at"] is not None:
            age = (time.time() - row["used_at"].timestamp()).total_seconds()
            if age <= self.grace:
                child = self.db.one("SELECT jti FROM refresh_tokens "
                                    "WHERE parent_jti = $1", row["jti"])
                if child:
                    return Decision("replay_within_grace", row["user_id"],
                                    row["family"], child["jti"])
            self._revoke_family(row["family"], row["user_id"], "reuse_detected")
            return Decision("reuse", row["user_id"], row["family"])
        if row["revoked_at"] is not None:
            return Decision("revoked", row["user_id"], row["family"])
        return Decision("expired", row["user_id"], row["family"])

    def _revoke_family(self, family: str, user_id: str, reason: str) -> None:
        self.db.run("UPDATE refresh_tokens SET revoked_at = now() "
                    "WHERE family = $1 AND revoked_at IS NULL", family)
        self.db.run("UPDATE access_denied SET revoked_at = now() "
                    "WHERE user_id = $1 AND revoked_at IS NULL", user_id)
        security_alert("refresh." + reason, user_id=user_id, family=family)
```

**Tests.**

```python
def test_second_use_of_a_spent_token_is_theft():
    svc = service()
    t1, meta = svc.issue("u1")
    assert svc.consume(t1).action == "issue"
    d = svc.consume(t1)
    assert d.action == "reuse"
    # The whole family, including the child, is dead.
    assert svc.db.one("SELECT count(*) c FROM refresh_tokens "
                      "WHERE family = $1 AND revoked_at IS NULL", meta["family"])["c"] == 0

def test_grace_window_returns_the_same_successor():
    svc = service(grace_seconds=10)
    t1, _ = svc.issue("u1")
    first = svc.consume(t1)
    second = svc.consume(t1)                  # lost response, client retries
    assert second.action == "replay_within_grace"
    assert second.child_jti == first.child_jti

def test_concurrent_consume_has_exactly_one_winner():
    svc = service()
    t1, _ = svc.issue("u1")
    with ThreadPoolExecutor(8) as ex:
        results = list(ex.map(lambda _: svc.consume(t1).action, range(8)))
    assert results.count("issue") == 1
    assert results.count("reuse") == 7
```

**Interview reasoning.** `UPDATE ... RETURNING` is the arbiter, so single-use is atomic without a lock. A replay is only possible if you leaked or the client is broken, so it is a strong theft signal. The grace window acknowledges that networks drop responses, and returning the *same* successor keeps the chain linear.

