#### Problem 6: Correct authorization layer: route map + scoped repositories + field projection

**Specification.** A fail-closed route→permission map, a repository API that requires the principal, and a serializer that drops unauthorized fields and errors on unclassified ones.

```python
from dataclasses import dataclass
from typing import Literal

Permission = Literal["orders:read", "orders:write", "orders:read_sensitive",
                     "users:read_basic", "users:read_sensitive", "refunds:approve"]

FIELD_PERMISSIONS: dict[str, dict[str, Permission]] = {
    "Order": {"id": "orders:read", "total_cents": "orders:read",
              "card_last4": "orders:read_sensitive", "customer_email": "orders:read_sensitive"},
    "User": {"id": "users:read_basic", "email": "users:read_basic",
             "phone": "users:read_sensitive", "ssn_last4": "users:read_sensitive"},
}

class AuthorizationError(Exception): pass

def project(principal: set[Permission], entity: str, row: dict) -> dict:
    table = FIELD_PERMISSIONS.get(entity)
    if table is None:
        raise AuthorizationError(f"entity {entity} has no field classification")
    out = {}
    for field, value in row.items():
        perm = table.get(field)
        if perm is None:
            raise AuthorizationError(f"{entity}.{field} is unclassified")   # fatal: fail the build
        if perm in principal:
            out[field] = value
    return out

class OrderRepo:
    def __init__(self, db, principal):
        self.db, self.p = db, principal

    async def get(self, order_id: str) -> dict:
        require(self.p, "orders:read")
        row = await self.db.fetchrow(
            "SELECT * FROM orders WHERE id = $1 AND tenant_id = $2 AND owner_id = $3",
            order_id, self.p.tenant, self.p.subject)
        if row is None:
            raise NotFound()        # indistinguishable from "not yours"
        return project(self.p.scopes, "Order", dict(row))

    async def list(self, status: str | None, limit: int) -> list[dict]:
        require(self.p, "orders:read")
        rows = await self.db.fetch(
            "SELECT * FROM orders WHERE tenant_id = $1 AND owner_id = $2 "
            "AND ($3::text IS NULL OR status = $3) "
            "ORDER BY created_at DESC LIMIT $4",
            self.p.tenant, self.p.subject, status, min(limit, 100))
        return [project(self.p.scopes, "Order", dict(r)) for r in rows]
```

The router-level fail-closed check:

```python
ROUTE_PERMISSIONS = {
    ("GET", "/v1/orders"): "orders:read",
    ("POST", "/v1/orders"): "orders:write",
    ("GET", "/v1/orders/{id}"): "orders:read",
    ("DELETE", "/v1/orders/{id}"): "orders:write",
    ("POST", "/v1/refunds/{id}/approve"): "refunds:approve",
}
PUBLIC_ROUTES = {("GET", "/healthz"), ("GET", "/v1/public/rates")}

def check_route(method: str, path: str, principal: Principal | None) -> None:
    if (method, path) in PUBLIC_ROUTES:
        return
    if principal is None:
        raise Unauthenticated()
    perm = ROUTE_PERMISSIONS.get((method, path))
    if perm is None:
        metrics.incr("authz.unmapped_route_total", path=path)
        raise AuthorizationError("no permission mapping")       # fail closed
    if perm not in principal.scopes:
        metrics.incr("authz.denied_total", perm=perm, path=path)
        raise Forbidden()
```

**Tests.** A principal from tenant B requesting tenant A's order → 404 with no body fields. A principal without `orders:read_sensitive` receives no `card_last4`. Adding a column to `SELECT *` in a test fixture makes the projection test fail with "unclassified." A new route with no map entry → 403.

**Interview reasoning.** Scoping in the query means the wrong-handler problem cannot leak data. `UnclassifiedField` as a fatal error turns "someone added a PII column" from a breach into a failing test. Fail-closed on unmapped routes means forgetting a permission is a 403, not a hole.

